    if (first == NULL || second == NULL || separation_rad == NULL || conditioning == NULL) {
        *separation_rad = 0.0;
        *conditioning = 0.0;
        return ADCS_E_NULL;
    }

    // Check for non-finite values first as per requirement grouping
    if (!adcs_is_finite_vec3(first) || !adcs_is_finite_vec3(second)) {
        *separation_rad = 0.0;
        *conditioning = 0.0;
        return ADCS_E_DEGENERATE;
    }

    double n1 = adcs_vec3_norm(first);
    double n2 = adcs_vec3_norm(second);

    // Check for degenerate magnitude
    if (n1 <= 1.0e-12 || n2 <= 1.0e-12) {
        *separation_rad = 0.0;
        *conditioning = 0.0;
        return ADCS_E_DEGENERATE;
    }

    // Normalize vectors
    adcs_vec3_t u = adcs_vec3_scale(first, 1.0 / n1);
    adcs_vec3_t v = adcs_vec3_scale(second, 1.0 / n2);

    // Calculate separation
    double dot = adcs_vec3_dot(&u, &v);
    if (dot < -1.0) dot = -1.0;
    if (dot > 1.0) dot = 1.0;
    *separation_rad = acos(dot);

    // Calculate conditioning
    adcs_vec3_t cr = adcs_vec3_cross(&u, &v);
    *conditioning = adcs_vec3_norm(&cr);

    return ADCS_OK;
}

