    if ((first == NULL) || (second == NULL) || (separation_rad == NULL) || (conditioning == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(first)) || (!adcs_is_finite_vec3(second))) {
        *separation_rad = 0.0;
        *conditioning = 0.0;
        return ADCS_E_NOT_FINITE;
    }

    adcs_vec3_t u, v;

    if (adcs_vec3_normalize(first, ADCS_EPS_NORM, &u) != ADCS_OK) {
        *separation_rad = 0.0;
        *conditioning = 0.0;
        return ADCS_E_DEGENERATE;
    }

    if (adcs_vec3_normalize(second, ADCS_EPS_NORM, &v) != ADCS_OK) {
        *separation_rad = 0.0;
        *conditioning = 0.0;
        return ADCS_E_DEGENERATE;
    }

    double dot_product = adcs_vec3_dot(&u, &v);
    double clamped_dot = ADCS_CLAMP(dot_product, -1.0, 1.0);
    *separation_rad = acos(clamped_dot);

    adcs_vec3_t cross_product = adcs_vec3_cross(&u, &v);
    *conditioning = adcs_vec3_norm(&cross_product);

    return ADCS_OK;
}

